def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_d = sum(1 for x in op if x == 'D')
    opp_c = n - opp_d
    my_d = sum(1 for x in me if x == 'D')

    if opp_d == n:
        return 'D'

    dD = dC = cD = cC = 0
    for i in range(1, n):
        if me[i - 1] == 'D':
            if op[i] == 'D':
                dD += 1
            else:
                dC += 1
        else:
            if op[i] == 'D':
                cD += 1
            else:
                cC += 1

    after_d = dD + dC
    after_c = cC + cD
    punish = dD / after_d if after_d else 0.0
    host = cD / after_c if after_c else opp_d / n

    if after_d:
        diff = punish - host
    elif opp_c / n > 0.85 and cD <= 1:
        diff = 0.6
    else:
        diff = 0.0

    recent_op = op[-10:] if n >= 10 else op
    recent_d = sum(1 for x in recent_op if x == 'D')

    recent_cC = recent_cD = 0
    for i in range(max(1, n - 10), n):
        if me[i - 1] == 'C':
            if op[i] == 'C':
                recent_cC += 1
            else:
                recent_cD += 1

    run_opp_d = 0
    for x in reversed(op):
        if x == 'D':
            run_opp_d += 1
        else:
            break

    retaliatory = after_d >= 2 and punish > 0.5 and diff > 0.35
    exploitable = after_d >= 1 and (dC / after_d > 0.65 or (punish < 0.45 and diff < 0.1))
    hostile = after_c >= 2 and host > 0.45 and opp_c / n < 0.65

    if opp_d == 0:
        if my_d > 0:
            return 'D'
        if n == 90 and rng.random() < 0.15:
            return 'D'
        return 'C'

    if hostile:
        return 'D'

    if n == 98:
        return 'C' if diff > 0.4 or retaliatory else 'D'

    if n == 97:
        return 'C' if diff > 0.55 or retaliatory else 'D'

    if op[-1] == 'D':
        if me[-1] == 'D':
            if run_opp_d >= 5:
                return 'D'
            if host > 0.5 or (recent_cC == 0 and recent_cD >= 3):
                return 'D'
            if exploitable and run_opp_d >= 2:
                return 'D'
            return 'C'
        else:
            if n >= 2 and me[-2] == 'D' and run_opp_d <= 2 and host < 0.35:
                return 'C'
            return 'D'

    if me[-1] == 'D':
        return 'D' if exploitable else 'C'

    return 'C'
